def _cooperative_preparation_tree(group, original_tree):
    """Retain whole original modules and invert every finite call substitution."""
    if group not in VIEW_SPECS:
        raise ValueError('only the three explicit preparation source modules are admitted')
    result = copy.deepcopy(original_tree)
    inverses = {}
    for index,node in enumerate(original_tree.body):
        if not isinstance(node,ast.FunctionDef) or node.name not in VIEW_SPECS[group]:
            continue
        expected = ast.parse(EXPECTED_SOURCE[group][node.name]).body
        if len(expected)!=1 or _dump(node)!=_dump(expected[0]):
            raise ValueError('complete reviewed preparation function changed: '+node.name)
        if any(isinstance(item,(ast.Yield,ast.YieldFrom)) for item in ast.walk(node)):
            raise ValueError('the admitted original preparation owner must be synchronous')
        spec = VIEW_SPECS[group][node.name]
        counts = {name:0 for name in spec}
        changes = []

        class Lift(ast.NodeTransformer):
            def visit_Call(self,item):
                item = self.generic_visit(item)
                if isinstance(item.func,ast.Name) and item.func.id in spec:
                    before = copy.deepcopy(item)
                    name = item.func.id
                    counts[name] += 1
                    item.func.id = spec[name][1]
                    after = ast.copy_location(ast.YieldFrom(value=item),item)
                    changes.append((before,copy.deepcopy(after)))
                    return after
                return item

        derived = Lift().visit(copy.deepcopy(node))
        if counts!={name:value[0] for name,value in spec.items()}:
            raise ValueError('exact preparation propagation count differs: '+node.name)
        remaining = list(changes)

        class Inverse(ast.NodeTransformer):
            def visit_YieldFrom(self,item):
                for position,(before,after) in enumerate(remaining):
                    if _dump(item)==_dump(after):
                        remaining.pop(position)
                        return ast.copy_location(copy.deepcopy(before),item)
                raise ValueError('unadmitted preparation yield-from')

        inverse = Inverse().visit(copy.deepcopy(derived))
        if remaining or _dump(inverse)!=_dump(node):
            raise ValueError('complete preparation function inverse differs: '+node.name)
        result.body[index] = derived
        inverses[index] = inverse
    if len(inverses)!=len(VIEW_SPECS[group]):
        raise ValueError('all complete preparation source owners are required')
    restored = copy.deepcopy(result)
    for index,inverse in inverses.items():
        restored.body[index] = inverse
    if _dump(restored)!=_dump(original_tree):
        raise ValueError('whole preparation source module inverse differs')
    return ast.fix_missing_locations(result)


class BattlePreparationPrograms(BattleScenePrograms):
    """Seven real Main calls reuse the actual Scene refresh and battle message owners.

    There is no fresh game state, scheduler or alternate wait class here.
    Parent00300 retains3CE; its existing display/campaign call owners retain
    every inner LONG until the original child has really returned.
    """

    def __init__(self,state: SceneState):
        super().__init__(state)
        self.preparation_modules = {group:importlib.import_module(path)
            for group,path in MODULE_PATHS.items()}
        self.preparation_originals = {}
        self.preparation_codes = {}
        self.preparation_views = {}
        self.preparation_namespaces = {}
        self.preparation_bindings = {}
        for group,module in self.preparation_modules.items():
            tree = ast.parse(inspect.getsource(module),filename=module.__file__)
            nodes = {node.name:node for node in tree.body if isinstance(node,ast.FunctionDef)}
            compiled = compile(tree,module.__file__,'exec',dont_inherit=True)
            for name,source in EXPECTED_SOURCE[group].items():
                original = getattr(module,name)
                if name not in nodes or _dump(nodes[name])!=_dump(ast.parse(source).body[0]) \
                        or type(original)is not FunctionType or original.__globals__ is not vars(module) \
                        or original.__module__!=module.__name__ or original.__name__!=name \
                        or original.__closure__ is not None or original.__code__.co_freevars \
                        or _code_shape(original.__code__)!=_code_shape(_top_code(compiled,name)):
                    raise ValueError('actual unwrapped whole preparation source required: '+name)
                self.preparation_originals[group,name] = original
                self.preparation_codes[group,name] = original.__code__
            derived = _cooperative_preparation_tree(group,tree)
            code = compile(derived,module.__file__,'exec',dont_inherit=True)
            namespace = dict(vars(module))
            self.preparation_namespaces[group] = namespace
            for name in VIEW_SPECS[group]:
                original = self.preparation_originals[group,name]
                view = FunctionType(_top_code(code,name),namespace,name,original.__defaults__,None)
                view.__kwdefaults__ = original.__kwdefaults__
                view.__annotations__ = dict(original.__annotations__)
                if not inspect.isgeneratorfunction(view) or view.__closure__ is not None:
                    raise ValueError('one whole closure-free preparation generator required: '+name)
                self.preparation_views[group,name] = view
        self._preparation_view_owners = dict(self.preparation_views)
        self._preparation_view_codes = {key:value.__code__ for key,value in self.preparation_views.items()}
        aliases = {'_preparation_view_'+group+'_'+name:value
            for (group,name),value in self.preparation_views.items()}
        aliases.update(_preparation_campaign_call=self.views['main','_campaign_call_fields'],
            _preparation_refresh=self._refresh,
            _preparation_battle_message=self._preparation_message)
        for group,namespace in self.preparation_namespaces.items():
            for name,value in aliases.items():
                if name in namespace:
                    raise ValueError('preparation alias must not replace any original business name')
                namespace[name] = value
                self.preparation_bindings[group,name] = value
        self.preparation_reused = {}
        for path,sources in EXPECTED_REUSED_SOURCE.items():
            module = importlib.import_module(path)
            tree = ast.parse(inspect.getsource(module),filename=module.__file__)
            compiled = compile(tree,module.__file__,'exec',dont_inherit=True)
            for name,source in sources.items():
                nodes = [node for node in tree.body if isinstance(node,(ast.FunctionDef,ast.ClassDef))
                    and node.name==name]
                owner = getattr(module,name)
                if len(nodes)!=1 or _dump(nodes[0])!=_dump(ast.parse(source).body[0]):
                    raise ValueError('complete reused preparation source differs: '+name)
                if isinstance(nodes[0],ast.FunctionDef) and (type(owner)is not FunctionType
                        or owner.__globals__ is not vars(module) or owner.__module__!=module.__name__
                        or owner.__closure__ is not None
                        or _code_shape(owner.__code__)!=_code_shape(_top_code(compiled,name))):
                    raise ValueError('actual reused preparation function identity required: '+name)
                self.preparation_reused[path,name] = (module,owner,
                    owner.__code__ if type(owner)is FunctionType else None)

    def require_current(self,state):
        super().require_current(state)
        if not hasattr(self,'preparation_originals'):
            return
        for (group,name),original in self.preparation_originals.items():
            if getattr(self.preparation_modules[group],name)is not original \
                    or original.__code__ is not self.preparation_codes[group,name]:
                raise ValueError('original preparation callable changed during suspension: '+name)
        if self.preparation_views.keys()!=self._preparation_view_owners.keys():
            raise ValueError('finite preparation continuation graph changed')
        for key,view in self._preparation_view_owners.items():
            if self.preparation_views[key]is not view or view.__code__ is not self._preparation_view_codes[key]:
                raise ValueError('whole preparation view identity changed: '+key[1])
        for (group,name),binding in self.preparation_bindings.items():
            if self.preparation_namespaces[group].get(name)is not binding:
                raise ValueError('private preparation binding changed: '+name)
        for (path,name),(module,owner,code) in getattr(self,'preparation_reused',{}).items():
            if getattr(module,name)is not owner or (code is not None and owner.__code__ is not code):
                raise ValueError('actual reused preparation owner changed: '+path+':'+name)

    def _preparation_message(self,state,frame):
        self.require_current(state)
        return (yield from self.battle_views['movement','present_battle_message_fields'](state,frame))

    def _campaign_child(self,state,frame,target,continuation):
        self.require_current(state)
        name = GAMEPLAY_CALLS.get((target,continuation))
        if name is not None:
            return (yield from self.preparation_views['gameplay',name](state,frame))
        if target==0x17F30:
            if continuation!=0xD14:
                raise MovementContinuationBoundary(target,frame,'preparation retreat requires actual17F30/D14 slot')
            return (yield from self.preparation_views['movement',
                'integrate_selected_officer_into_packed_group_fields'](state,frame))
        if target in (0x17A16,0x17A5A,0x17A9E):
            raise MovementContinuationBoundary(target,frame,'battle preparation child has a different real caller')
        if target==0xAF48 and continuation in MAIN_REFRESH_RETURNS:
            return (yield from self._refresh(SceneRefreshMemory(state),frame))
        return (yield from super()._campaign_child(state,frame,target,continuation))

    def _display_child(self,state,frame,target,continuation):
        self.require_current(state)
        if target in MAIN_ENTRIES:
            if continuation!=0x3CE:
                raise MovementContinuationBoundary(target,frame,'preparation Main entry requires original3CE slot')
            return (yield from self.preparation_views['main',MAIN_ENTRIES[target]](state,frame))
        return (yield from super()._display_child(state,frame,target,continuation))

    def main_scene_call(self,state,frame,target,continuation):
        if target not in MAIN_ENTRIES:
            return (yield from super().main_scene_call(state,frame,target,continuation))
        self.require_current(state)
        if self._started or continuation!=0x3CE:
            raise ValueError('one complete original Main45C..474 preparation invocation required')
        self._started = True
        return (yield from self.views['display','display_call_fields'](state,frame,target,continuation))
